        <section class="available-tools container">
          <header class="section-title">Available Tools</header>
          <span class="tool-names container">
            ${
    (() => {
      const maxVisibleTools = 30;
      const visibleTools = toolNames.slice(0, maxVisibleTools);
      const remainingTools = toolNames.length - visibleTools.length;
      const toolBadges = visibleTools
        .map((tool: { name: string; description: string }) =>
          `<span class="badge">${tool.name}</span>`
        )
        .join("\n");
      const remainingBadge = remainingTools > 0
        ? `\n<span class="badge">AND ${remainingTools} MORE</span>`
        : "";
      return `${toolBadges}${remainingBadge}`;
    })()
  }
